        --color-page: #f6f8fb;
        --color-surface: #ffffff;
        --color-text: #172033;
        --color-muted: #4f5f74;
        --color-border: #aeb9c8;
        --color-border-strong: #64748b;
        --color-primary: #2157d6;
        --color-primary-hover: #1743ad;
        --color-error: #b42318;
        --color-success: #176b3a;
        --shadow-card: 0 24px 60px #cad3e2;
        --radius-lg: 28px;
        --radius-md: 14px;
        --radius-sm: 10px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 320px;
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system,
          BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--color-text);
        background:
          radial-gradient(circle at top left, #d9e7ff 0, transparent 34rem),
          linear-gradient(135deg, #f8fbff 0%, var(--color-page) 100%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: var(--radius-sm);
        color: var(--color-surface);
        background: var(--color-primary);
        transform: translateY(-150%);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(1120px, 100%);
        margin: 0 auto;
        padding: 2rem clamp(1rem, 4vw, 3rem) 4rem;
      }

      .site-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        gap: 1rem;
        padding: 0.5rem 0 3rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        font-weight: 800;
        letter-spacing: -0.02em;
      }

      .brand-mark {
        display: grid;
        width: 2.25rem;
        height: 2.25rem;
        place-items: center;
        border-radius: 0.8rem;
        color: var(--color-surface);
        background: var(--color-primary);
      }

      .support-note {
        margin: 0;
        color: var(--color-muted);
        font-size: 0.95rem;
      }

      main {
        display: grid;
        grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
        gap: clamp(2rem, 5vw, 5rem);
        align-items: center;
      }

      .hero {
        min-width: 0;
      }

      .eyebrow {
        display: inline-flex;
        margin: 0 0 1rem;
        padding: 0.35rem 0.7rem;
        border: 1px solid #b8c8ee;
        border-radius: 999px;
        color: #193f92;
        background: #eef4ff;
        font-size: 0.9rem;
        font-weight: 700;
      }

      h1 {
        margin: 0;
        max-width: 11ch;
        font-size: clamp(2.75rem, 8vw, 5.75rem);
        line-height: 0.93;
        letter-spacing: -0.07em;
      }

      .hero-text {
        max-width: 34rem;
        margin: 1.5rem 0 0;
        color: var(--color-muted);
        font-size: clamp(1rem, 2vw, 1.2rem);
      }

      .contact-card {
        min-width: 0;
        padding: clamp(1.25rem, 3vw, 2rem);
        border: 1px solid #d5dce7;
        border-radius: var(--radius-lg);
        background: var(--color-surface);
        box-shadow: var(--shadow-card);
      }

      .form-heading {
        margin: 0 0 0.4rem;
        font-size: clamp(1.5rem, 3vw, 2rem);
        letter-spacing: -0.03em;
      }

      .form-intro {
        margin: 0 0 1.5rem;
        color: var(--color-muted);
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
        margin-bottom: 1.1rem;
      }

      label {
        font-weight: 750;
      }

      .required-marker,
      .optional-marker {
        font-size: 0.95rem;
        font-weight: 700;
      }

      .required-marker {
        color: var(--color-error);
      }

      .optional-marker {
        color: var(--color-muted);
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        padding: 0.85rem 1rem;
        border: 1px solid var(--color-border);
        border-radius: var(--radius-md);
        color: var(--color-text);
        background: var(--color-surface);
        font: inherit;
        transition:
          border-color 160ms ease,
          box-shadow 160ms ease;
      }

      input:hover {
        border-color: var(--color-border-strong);
      }

      input:focus {
        border-color: var(--color-primary);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #bfd2ff;
      }

      input[aria-invalid="true"] {
        border-color: var(--color-error);
      }

      .field-help,
      .field-error {
        margin: 0;
        font-size: 0.94rem;
      }

      .field-help {
        color: var(--color-muted);
      }

      .field-error {
        display: none;
        color: var(--color-error);
        font-weight: 700;
      }

      .field-error.is-visible {
        display: block;
      }

      .submit-button {
        width: 100%;
        min-height: 3.35rem;
        margin-top: 0.35rem;
        border: 0;
        border-radius: var(--radius-md);
        color: var(--color-surface);
        background: var(--color-primary);
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition:
          background-color 160ms ease,
          transform 160ms ease;
      }

      .submit-button:hover {
        background: var(--color-primary-hover);
      }

      .submit-button:active {
        transform: translateY(1px);
      }

      .submit-button:focus {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #bfd2ff;
      }

      .form-status {
        min-height: 1.5rem;
        margin: 1rem 0 0;
        color: var(--color-success);
        font-weight: 750;
      }

      @media (max-width: 760px) {
        .site-header,
        main {
          display: block;
        }

        .support-note {
          margin-top: 0.75rem;
        }

        .hero {
          margin-bottom: 2rem;
        }

        h1 {
          max-width: 12ch;
        }
      }

      @media (max-width: 380px) {
        .page-shell {
          padding-inline: 0.75rem;
        }

        .contact-card {
          padding: 1rem;
          border-radius: 20px;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }

      @media (forced-colors: active) {
        body,
        .contact-card {
          background: Canvas;
        }

        .brand-mark,
        .skip-link,
        .submit-button {
          border: 1px solid ButtonBorder;
          color: ButtonText;
          background: ButtonFace;
        }

        .eyebrow {
          border-color: CanvasText;
          color: CanvasText;
          background: Canvas;
        }

        input:focus,
        .submit-button:focus {
          outline: 3px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const fields = [
        {
          id: "full-name",
          name: "fullName",
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          errorId: "full-name-error",
          requiredMessage: "Enter your full name.",
        },
        {
          id: "email-address",
          name: "emailAddress",
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          errorId: "email-address-error",
          requiredMessage: "Enter your email address.",
          patternMessage: "Enter an email address in the format name@example.com.",
        },
        {
          id: "phone-number",
          name: "phoneNumber",
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          helperId: "phone-number-help",
          errorId: "phone-number-error",
          helperText: "Use 10 to 15 digits. You may include spaces, dashes, parentheses, or a leading plus sign.",
          patternMessage: "Enter a phone number with 10 to 15 digits, using only numbers, spaces, dashes, parentheses, or a leading plus sign.",
        },
      ];

      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const phoneAllowedPattern = /^\+?[0-9\s().-]+$/;

      function Field({ id, label, type, autocomplete, required, helperId, helperText, errorId }) {
        const describedBy = [helperId, errorId].filter(Boolean).join(" ");
        const marker = required
          ? '<span class="required-marker" aria-hidden="true">*</span>'
          : '<span class="optional-marker">(optional)</span>';

        return `
          <div class="form-field">
            <label for="${id}">${label} ${marker}</label>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              autocomplete="${autocomplete}"
              ${required ? "required" : ""}
              aria-invalid="false"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            />
            ${
              helperText
                ? `<p class="field-help" id="${helperId}">${helperText}</p>`
                : ""
            }
            <p class="field-error" id="${errorId}" aria-live="polite"></p>
          </div>
        `;
      }

      function ContactForm() {
        return `
          <a class="skip-link" href="#main-content">Skip to main content</a>
          <div class="page-shell">
            <header class="site-header">
              <div class="brand" aria-label="Acme Support">
                <span class="brand-mark" aria-hidden="true">A</span>
                <span>Acme Support</span>
              </div>
              <p class="support-note">Average response time: under 1 business day</p>
            </header>
            <main id="main-content">
              <section class="hero" aria-labelledby="support-title">
                <p class="eyebrow">Support request</p>
                <h1 id="support-title">How can we help?</h1>
                <p class="hero-text">
                  Send our team your contact details and we will route your request to the right specialist.
                </p>
              </section>
              <section class="contact-card" aria-labelledby="form-title">
                <h2 class="form-heading" id="form-title">Contact support</h2>
                <p class="form-intro">Fields marked with an asterisk (*) are required.</p>
                <form id="support-form" novalidate>
                  ${fields.map(Field).join("")}
                  <button class="submit-button" type="submit">Submit request</button>
                  <p class="form-status" id="form-status" aria-live="polite"></p>
                </form>
              </section>
            </main>
          </div>
        `;
      }

      function validateField(field, value) {
        const trimmedValue = value.trim();

        if (field.required && !trimmedValue) {
          return field.requiredMessage;
        }

        if (field.name === "emailAddress" && trimmedValue && !emailPattern.test(trimmedValue)) {
          return field.patternMessage;
        }

        if (field.name === "phoneNumber" && trimmedValue) {
          const digitCount = trimmedValue.replace(/\D/g, "").length;
          const hasValidCharacters = phoneAllowedPattern.test(trimmedValue);

          if (!hasValidCharacters || digitCount < 10 || digitCount > 15) {
            return field.patternMessage;
          }
        }

        return "";
      }

      function setFieldError(input, errorElement, message) {
        input.setAttribute("aria-invalid", message ? "true" : "false");
        errorElement.textContent = message;
        errorElement.classList.toggle("is-visible", Boolean(message));
      }

      function attachValidation() {
        const form = document.querySelector("#support-form");
        const status = document.querySelector("#form-status");

        fields.forEach((field) => {
          const input = document.querySelector(`#${field.id}`);
          const errorElement = document.querySelector(`#${field.errorId}`);

          input.addEventListener("input", () => {
            setFieldError(input, errorElement, validateField(field, input.value));
            status.textContent = "";
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          let firstInvalidInput = null;

          fields.forEach((field) => {
            const input = document.querySelector(`#${field.id}`);
            const errorElement = document.querySelector(`#${field.errorId}`);
            const message = validateField(field, input.value);
            setFieldError(input, errorElement, message);

            if (message && !firstInvalidInput) {
              firstInvalidInput = input;
            }
          });

          if (firstInvalidInput) {
            status.textContent = "";
            firstInvalidInput.focus();
            return;
          }

          form.reset();
          fields.forEach((field) => {
            const input = document.querySelector(`#${field.id}`);
            const errorElement = document.querySelector(`#${field.errorId}`);
            setFieldError(input, errorElement, "");
          });
          status.textContent = "Thanks. Your support request is ready to send.";
        });
      }

      document.querySelector("#app").innerHTML = ContactForm();
      attachValidation();
    </script>
  </body>
</html>
